            businessID: preprocessed.businessID,
            startTime: startTime.toISOString(),
            endTime: endTime.toISOString(),
        });
        if (data.length > 0) {
            const [{ label_paigo_application_id, label_paigo_dimension_id, label_paigo_service_id }] = data;
            dimensionId = label_paigo_dimension_id;
            serviceId = label_paigo_service_id;
            applicationId = label_paigo_application_id;
        } else {
