        // determine for each aggregation interval if there exists a time when the pod was "ready"
        let pods;
        try {
            const podsJoinedByCustomerId = await Promise.all(
                timeSegments.map(
                    async ({ startTime, endTime }): Promise<{ startTime: Date; endTime: Date; data: Array<any> }> => {
                        pods = await this.InfluxService.getPodsInReadyState({ startTime, endTime, businessID });
                        const joinedResults = pods.reduce((acc, { table, _value, pod, _measurement, ...rest }) => {
                            // Join pods with their labels, this done outside of influx for now
                            if (!acc[pod]) {
                                acc[pod] = {};
                            }
                            if (_measurement === 'paigo_kube_pod_labels') {
                                const { label_paigo_customer_id } = rest;
                                if (label_paigo_customer_id) {
                                    acc[pod] = { ...acc[pod], customerId: label_paigo_customer_id };
                                }
                            }
                            if (_measurement === 'paigo_kube_pod_container_status_running') {
                                acc[pod] = { ...acc[pod], usage: _value };
                            }
                            return acc;
                        }, {});
                        return { startTime, endTime, data: joinedResults };
                    }
                )
            );

            // Aggregate the results to the customer Level
            const uniqueIdsUpTimeHours = podsJoinedByCustomerId.reduce(
                (acc, { startTime, endTime, data }): Record<string, any> => {
                    const podsKeys = Object.keys(data);
                    const isoStartTime = startTime.toISOString();
                    const isoEndTime = endTime.toISOString();
                    // Below we map which segments of time are in use by which customer
                    // Importantly, if there are overlapping segements for pods (IE: Multiple pods per customer that are up in the same window)
                    // It doesn't matter since all we need to have is a single "Ready" value to be considered "up"
                    podsKeys.forEach((key) => {
                        const { customerId, usage } = data[key];
                        if (customerId) {
                            if (!acc[customerId]) {
                                acc[customerId] = {};
                            }
                            acc[customerId][`${isoStartTime}##${isoEndTime}`] = usage;
                        }
                    });
                    return acc;
                },
                {}
            );
            DimensionAggregationService.logger.log(`uniqueIdsUpTimeHours: ${JSON.stringify(uniqueIdsUpTimeHours)}`);

            const filteredKeys = Object.keys(uniqueIdsUpTimeHours).filter((customerId) =>
                customerIds.includes(customerId)
            );"""
