            volumeID,
            businessID,
            size,
            iops,
            volumeType,
            tags = [],
            state,
            throughput,
            availabilityZone,
            region,
        } = ebsVolumeEntity;
        const volumeEntityPoint = influxService.getPoint(EbsVolumeDataGathererEntity._measurement);

        volumeEntityPoint.tag('volumeID', volumeID);
