import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException, forwardRef } from '@nestjs/common';
import { PublicAPIDimensionsModule } from '../dimensions/dimensions.module';
import { InfluxModule } from '../influx/influx.module';
import { MeasurementConfigModule } from '../measurement-config/measurement-config.module';
import { PublicAPIOfferingModule } from '../offering/offering.module';
import { PublicAPIServicesModule } from '../services/services.module';
import { PublicAPICustomerModule } from '../customer/customer.module';
import { UsageService } from './usage.service';
import { InfluxService } from '../influx/influx.service';
import { CustomerService } from '../customer/customer.service';
import { MeasurementConfigService } from '../measurement-config/measurement-config.service';
import { DimensionsService } from '../dimensions/dimensions.service';
import { ServicesService } from '../services/services.service';
import { OfferingService } from '../offering/offering.service';
import { aggregationInterval } from '../dimensions/dto/create-dimension.dto';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';
import { UsageEntity } from './entities/usage.entity';

describe('UsageService', () => {
    let service: UsageService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [UsageService],
            imports: [
                InfluxModule,
                MeasurementConfigModule,
                PublicAPIDimensionsModule,
                forwardRef(() => PublicAPIServicesModule),
                PublicAPIOfferingModule,
                forwardRef(() => PublicAPICustomerModule),
            ],
        }).compile();

        service = module.get<UsageService>(UsageService);
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });
});

describe('UsageService usage for a customer', () => {
    let service: UsageService;
    const offering = {
        offeringId: 'off-1',
        offeringName: 'my offering',
        dimensions: [
            { dimensionId: 'dim-1', aggregationInterval: aggregationInterval.hour },
            { dimensionId: 'dim-2', aggregationInterval: aggregationInterval.hour },
        ],
    };
    const getAggregateUsageForDimension = jest.fn(async () => [{ dimensionId: 'dim-1', usage: [] }]);
    const findOne = jest.fn(async () => ({
        data: [{ customerId: 'customer-1', offeringId: 'off-1', offering }],
        message: 'Found Customer',
    }));

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [UsageService] })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return { getAggregateUsageForDimension };
                }
                if (token === CustomerService) {
                    return { findOne };
                }
                if (
                    token === MeasurementConfigService ||
                    token === DimensionsService ||
                    token === ServicesService ||
                    token === OfferingService
                ) {
                    return {};
                }
            })
            .compile();
        service = module.get<UsageService>(UsageService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('aggregates with the customerId and the dimensions of the customer offering', async () => {
        const usage = await service.findUsageForCustomer(
            { customerId: 'customer-1', businessID: 'myCoolCorp' },
            {
                startTime: '2023-01-01T00:00:00Z',
                endTime: '2023-01-02T00:00:00Z',
                aggregationInterval: aggregationInterval.day,
            }
        );
        expect(findOne).toBeCalledWith({ customerId: 'customer-1', businessID: 'myCoolCorp' });
        expect(getAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                customerId: 'customer-1',
                clientID: 'customer-1',
                businessID: 'myCoolCorp',
                startTime: '2023-01-01T00:00:00Z',
                endTime: '2023-01-02T00:00:00Z',
                offeringDocument: {
                    offeringId: 'off-1',
                    offeringName: 'my offering',
                    dimensions: [
                        { dimensionId: 'dim-1', aggregationInterval: aggregationInterval.day },
                        { dimensionId: 'dim-2', aggregationInterval: aggregationInterval.day },
                    ],
                },
            })
        );
        expect(usage).toEqual([{ dimensionId: 'dim-1', usage: [] }]);
    });

    it('keeps the dimension defined aggregation interval when it is not overridden', async () => {
        await service.findUsageForCustomer({ customerId: 'customer-1', businessID: 'myCoolCorp' }, {});
        const [[{ offeringDocument, startTime, endTime }]] = getAggregateUsageForDimension.mock
            .calls as unknown as Array<Array<any>>;
        expect(offeringDocument.dimensions).toEqual(offering.dimensions);
        expect(new Date(endTime).getTime() - new Date(startTime).getTime()).toEqual(864e5);
    });

    it('conflicts when the customer has no offering attached', async () => {
        findOne.mockImplementationOnce(
            async () => ({ data: [{ customerId: 'customer-1' }], message: 'Found Customer' } as any)
        );
        await expect(
            service.findUsageForCustomer({ customerId: 'customer-1', businessID: 'myCoolCorp' }, {})
        ).rejects.toThrow(ConflictException);
        expect(getAggregateUsageForDimension).not.toBeCalled();
    });

    it('publishes the customerId on a created measurement', async () => {
        const publish = jest.spyOn(StandardMeasurementEntity, 'publish').mockImplementation(() => undefined);
        await service.create({
            businessID: 'myCoolCorp',
            customerId: 'customer-1',
            dimensionId: 'dim-1',
            recordValue: '10',
            timeStamp: '2023-01-01T00:00:00Z',
            metadata: {},
        });
        expect(publish).toBeCalledWith(
            expect.objectContaining({
                businessID: 'myCoolCorp',
                customerId: 'customer-1',
                dimensionId: 'dim-1',
                recordValue: 10,
                _measurement: UsageEntity._measurement,
            })
        );
        publish.mockRestore();
    });
});

