import { MeasurementFormat } from './measurement.interface';
import { StandardMeasurementEntity } from './standardMeasurement.entity';
import {
    PreProcessorMeasurementType,
    StandardMeasurementPreProcessorEntity,
} from './standardMeasurementPreProcessor';
import { InfluxService } from '../../influx/influx.service';
import { UsageEntity } from '../../usage/entities/usage.entity';

describe('StandardMeasurement', () => {
    const measurement = {
        businessID: 'myCoolCorp',
        customerId: 'customer-1',
        dimensionId: 'dim-1',
        recordValue: 12,
        timeStamp: '2023-01-01T00:00:00.000Z',
        metadata: { environment: 'staging' },
        _measurement: UsageEntity._measurement,
    };

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('keeps the customerId on the entity', () => {
        const entity = new StandardMeasurementEntity(measurement);
        expect(entity.customerId).toEqual('customer-1');
    });

    it('tags the customerId on the influx point', () => {
        const tag = jest.fn();
        const timestamp = jest.fn();
        const floatField = jest.fn();
        const influxService = {
            getPoint: () => ({ tag, timestamp, floatField }),
        } as unknown as InfluxService;
        MeasurementFormat.getPointForm(new StandardMeasurementEntity(measurement), influxService);
        expect(tag).toBeCalledWith('customerId', 'customer-1');
        expect(tag).toBeCalledWith('dimensionId', 'dim-1');
        expect(tag).toBeCalledWith('businessID', 'myCoolCorp');
        expect(tag).toBeCalledWith('metadata_environment', 'staging');
        expect(tag.mock.calls.map(([key]) => key)).not.toContain('serviceId');
        expect(tag.mock.calls.map(([key]) => key)).not.toContain('applicationId');
    });

    it('restores the customerId from the db model', () => {
        const restored = MeasurementFormat.toEntity({
            _time: measurement.timeStamp,
            _value: 12,
            _field: 'recordValue',
            _measurement: UsageEntity._measurement,
            businessID: 'myCoolCorp',
            customerId: 'customer-1',
            dimensionId: 'dim-1',
            metadata_environment: 'staging',
            recordValue: 12,
        } as never);
        expect(restored.customerId).toEqual('customer-1');
        expect(restored.dimensionId).toEqual('dim-1');
        expect(restored.metadata).toEqual({ environment: 'staging' });
    });

    it('only allows the customer and dimension paigo tags', () => {
        expect(StandardMeasurementEntity.allowedTags).toEqual(['paigoCustomerId', 'paigoDimensionId']);
        expect(
            StandardMeasurementEntity.awsTagKeyReducer([
                { Key: 'paigoCustomerId', Value: 'customer-1' },
                { Key: 'paigoDimensionId', Value: 'dim-1' },
                { Key: 'paigoServiceId', Value: 'service-1' },
            ])
        ).toEqual({ paigoCustomerId: 'customer-1', paigoDimensionId: 'dim-1' });
    });

    it('maps the kubernetes labels of an agent measurement to the customerId and dimensionId', async () => {
        const publish = jest.spyOn(StandardMeasurementEntity, 'publish').mockImplementation(() => undefined);
        const influxService = {
            getLatestPodLabelsByID: jest.fn(async () => [
                { label_paigo_customer_id: 'customer-1', label_paigo_dimension_id: 'dim-1' },
            ]),
        } as unknown as InfluxService;
        const preProcessed = new StandardMeasurementPreProcessorEntity(
            '0.05',
            'myCoolCorp',
            PreProcessorMeasurementType.AGENT,
            { pod: 'my-pod' },
            measurement.timeStamp
        );
        await StandardMeasurementPreProcessorEntity.createStandardMeasurement(preProcessed, 'my-pod', influxService);
        expect(publish).toBeCalledWith(
            expect.objectContaining({
                businessID: 'myCoolCorp',
                customerId: 'customer-1',
                dimensionId: 'dim-1',
                recordValue: 0.05,
                _measurement: UsageEntity._measurement,
            })
        );
        publish.mockRestore();
    });
});

